<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Cache;
use App\Services\{Access,ReportData,Letters,Reminders};
class DashboardController {
 public function index(){Access::menu('dashboard');if(!Cache::has('reminders_checked')){Reminders::run();Cache::put('reminders_checked',true,600);}$u=auth()->user();$ids=Access::ids();$citizen=$u->roleCode()==='WARGA';$q=ReportData::residents()->where('w.status','aktif');if($citizen)$q->where('k.id',DB::table('warga')->where('id',$u->warga_id)->value('kartu_keluarga_id'));$total=(clone $q)->count();$kk=(clone $q)->distinct()->count('k.id');$pending=Letters::query()->whereIn('p.status',['pending_rt','pending_rw'])->count();$issued=Letters::query()->where('p.status','terbit')->count();$guests=DB::table('tamu_menginap as g')->join('hunian as h','h.id','=','g.hunian_id')->whereIn('h.rt_id',$ids)->whereNull('g.deleted_at')->whereNull('g.selesai_aktual')->where('g.mulai','<=',now())->count();$renters=DB::table('sewa_penghuni as g')->join('hunian as h','h.id','=','g.hunian_id')->whereIn('h.rt_id',$ids)->whereNull('g.deleted_at')->whereNull('g.tanggal_keluar_aktual')->where('g.tanggal_masuk','<=',today())->count();$recent=Letters::query()->orderByDesc('p.id')->limit(5)->get();$series=[];$max=1;for($i=5;$i>=0;$i--){$m=now()->subMonthsNoOverflow($i);$values=[];foreach(['masuk','keluar','lahir','mati'] as $jenis){$n=DB::table('mutasi')->whereIn('rt_id',$ids)->where('jenis',$jenis)->where('status','tercatat')->whereNull('deleted_at')->whereBetween('tanggal_peristiwa',[$m->copy()->startOfMonth()->toDateString(),$m->copy()->endOfMonth()->toDateString()])->count();$values[]=$n;$max=max($max,$n);}$series[]=['month'=>$m->format('M'),'values'=>$values];}return view('dashboard',compact('citizen','total','kk','pending','issued','guests','renters','recent','series','max'));}
 public function notifications(){Access::menu('notifikasi');$rows=DB::table('notifikasi')->where('penerima_id',auth()->id())->orderByDesc('id')->paginate(20);return view('notifications',compact('rows'));}
 public function readNotification(int $id){$n=DB::table('notifikasi')->where('id',$id)->where('penerima_id',auth()->id())->first();abort_unless($n,404);DB::table('notifikasi')->where('id',$id)->update(['dibaca_pada'=>now(),'updated_at'=>now()]);return back()->with('success','Notifikasi ditandai sudah dibaca.');}
}
